function validate([s, k]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 10^5 characters.';
  if (!/^[1-9]+$/.test(s)) return 's may contain only the digits 1 to 9.';
  if (!Number.isInteger(k) || k < 1 || k > 1000000000) return 'k is an integer from 1 to 10^9.';
  return null;
}

