function minimumPartition(s, k) {
  let closed = 0;
  let value = 0;
  for (let i = 0; i < s.length; i++) {
    const digit = s.charCodeAt(i) - 48;
    if (digit > k) return -1;
    if (value * 10 + digit > k) {
      closed++;
      value = 0;
    }
    value = value * 10 + digit;
  }
  return closed + 1;
}

