function minimumPartition(s, k) {
  const n = s.length;
  const best = new Array(n + 1).fill(Infinity);
  best[0] = 0;
  for (let end = 1; end <= n; end++) {
    for (let start = Math.max(0, end - 10); start < end; start++) {
      if (Number(s.slice(start, end)) <= k && best[start] + 1 < best[end]) best[end] = best[start] + 1;
    }
  }
  return best[n] === Infinity ? -1 : best[n];
}

