function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(8000, 10000) : int(1, 10);
  const high = int(1, 9);
  let s = '';
  for (let i = 0; i < n; i++) s += String(int(1, high));
  let k;
  const pick = rand();
  if (pick < 0.15) k = int(1, 9);
  else if (pick < 0.3) k = 1000000000;
  else k = Math.max(1, Math.min(1000000000, Math.floor(Math.pow(10, rand() * 9.2))));
  return [s, k];
}
